    let beneath = h.app.widgets.iter().filter(|(w, r)| w.starts_with("source:folder:") && r.contains(pinned.center())).count();
    assert_eq!(beneath, 1, "a folder row lies under the middle of the pinned header");
    let from = row(&h).center();
